// HasMap applies the HasEdge predicate on the "map" edge.
func HasMap() predicate.CampaignMapPin {
	return predicate.CampaignMapPin(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MapTable, MapColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMapWith applies the HasEdge predicate on the "map" edge with a given conditions (other predicates).
func HasMapWith(preds ...predicate.CampaignMap) predicate.CampaignMapPin {
	return predicate.CampaignMapPin(func(s *sql.Selector) {
		step := newMapStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CampaignMapPin) predicate.CampaignMapPin {
	return predicate.CampaignMapPin(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CampaignMapPin) predicate.CampaignMapPin {
	return predicate.CampaignMapPin(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CampaignMapPin) predicate.CampaignMapPin {
	return predicate.CampaignMapPin(sql.NotPredicates(p))
}
